SELECT R.* FROM ( SELECT COUNT(*) OVER() AS TOTAL_RECORD_COUNT, ROW_NUMBER() OVER (ORDER BY A.CODE DESC) AS RNUM, A.CODE_ID, B.CODE_ID_NM, A.CODE, A.CODE_NM, A.CODE_DC, A.USE_AT, A.CODE_ETC1, A.CODE_ETC2, TO_CHAR(A.LAST_UPDT_PNTTM, 'YYYY-MM-DD AM HH12:MI') AS LAST_UPDT_PNTTM, A.LAST_UPDUSR_ID FROM COMTCCMMNDETAILCODE A INNER JOIN COMTCCMMNCODE B ON A.CODE_ID = B.CODE_ID WHERE 1=1
AND B.CODE_ID = #{codeId}
) R WHERE 1=1 ORDER BY REPLACE(CODE, CONCAT(CODE_ID, '_'), '') ASC

SELECT A.CODE,  A.CODE_NM, A.CODE_DC, A.CODE_ETC1, A.CODE_ETC2, A.USE_AT, A.CODE_ID
FROM COMTCCMMNDETAILCODE A
WHERE A.CODE = #{code}

SELECT A.CODE AS code, A.CODE_NM AS codeNm, A.CODE_DC AS codeDc, A.USE_AT AS useAt FROM COMTCCMMNDETAILCODE A WHERE A.CODE_ID = #{params.code}
AND REPLACE(A.CODE_NM, ':','') >= #{params.nowData}
AND REPLACE(A.CODE_NM, ':','') > #{params.overData}
AND CAST(CODE_DC AS INTEGER) BETWEEN CAST(REPLACE(#{params.startCode}, CONCAT(#{params.code}, '_'), '') AS INTEGER) AND CAST(REPLACE(#{params.endCode}, CONCAT(#{params.code}, '_'), '') AS INTEGER)
AND A.CODE_NM NOT IN
#{item}
AND REPLACE(a.CODE_NM, ':','') NOT LIKE CONCAT('%', #{params.notSearch})
AND USE_AT ='Y'
ORDER BY CAST(CODE_DC AS INTEGER) ASC
ORDER BY CODE ASC

SELECT     A.CODE AS code, A.CODE_NM AS codeNm, A.CODE_DC AS codeDc, A.USE_AT AS useAt
FROM COMTCCMMNDETAILCODE A
WHERE A.CODE_ID = #{codeId}

    AND A.CODE_DC = #{searchCodedc}

AND A.USE_AT ='Y'
